export type LawCard = {
  id: string;
  name: string;
  alias: string;
  date: string;
  purpose: string;
  points: string[];
  example: string;
  remember: string;
  url: string;
};

const boe = (path: string) => `https://www.boe.es/eli/${path}/con`;
const law = (id: string, name: string, alias: string, date: string, purpose: string, points: string[], example: string, remember: string, url: string): LawCard => ({ id, name, alias, date, purpose, points, example, remember, url });

export const lawFamilies: { id: string; title: string; groups: string; laws: LawCard[] }[] = [
  { id: 'procedimiento', title: 'Actuación administrativa y régimen local', groups: 'Grupos I y II; aplicación transversal', laws: [
    law('lpac', 'Ley 39/2015, del Procedimiento Administrativo Común de las Administraciones Públicas', 'LPAC · LPACAP · Ley 39/2015', '1 de octubre de 2015', 'Cómo se tramita un asunto y qué garantías tiene la persona interesada.', [
      "Quién es interesado: no es cualquier persona que tenga curiosidad. Es quien solicita algo como titular de un derecho o interés legítimo, quien puede ver afectado un derecho o quien comparece a tiempo con un interés legítimo afectado. Si pides una licencia eres interesado; si denuncias un ruido no adquieres automáticamente esa condición.",
      "Representación: puedes actuar personalmente o mediante representante. Para solicitar, recurrir, desistir o renunciar debe acreditarse la representación; para actuaciones de mero trámite se presume. Una persona que te acompaña a la oficina no se convierte por eso en tu representante.",
      "Registro: deja constancia de qué presentaste y cuándo. Recibes un justificante y el escrito se dirige al órgano competente. Por ejemplo, registrar una solicitud acredita su presentación, pero no significa que ya esté concedida.",
      "Relación electrónica: las personas jurídicas y otros sujetos del art. 14.2 están obligados a utilizarla. Las personas físicas pueden elegir salvo obligación aplicable. Si una asociación debe presentar electrónicamente y entrega papel, se le requiere subsanar y la fecha relevante será la de presentación electrónica.",
      "Solicitud y subsanación: la petición identifica al interesado y explica hechos y lo solicitado. Si falta un requisito, normalmente hay 10 días para subsanar. Si no lo haces, puede declararse tu desistimiento mediante resolución; la oficina no puede simplemente fingir que nunca presentaste nada.",
      "Plazos y resolución: los días se entienden hábiles salvo previsión de naturales; se excluyen sábados, domingos y festivos. La Administración debe resolver y notificar dentro del plazo del procedimiento; si no se fija, son 3 meses. Que se pida un informe no permite paralizar indefinidamente el expediente.",
      "Instrucción: se reúne la información necesaria mediante alegaciones, prueba e informes. La audiencia permite conocer lo actuado y defenderse antes de resolver cuando corresponde. Por ejemplo, puedes aportar una medición que contradiga un dato utilizado para denegar tu solicitud.",
      "Silencio: si vence el plazo sin respuesta, la ley atribuye un efecto a esa inactividad. En solicitudes la regla general es estimatoria, con importantes excepciones. En responsabilidad patrimonial el silencio es negativo; no se puede afirmar que toda solicitud presentada queda concedida por esperar.",
      "Acto y notificación: resolver decide el asunto; notificar comunica la decisión. Debe indicarse el texto y los recursos con órgano y plazo. Una notificación incompleta puede afectar a efectos y plazos sin convertir necesariamente el acto en nulo.",
      "Revisión y recursos: alzada si no se agota la vía administrativa; reposición potestativa, como regla común, si se agota. Se añaden revisión de oficio y revisión extraordinaria para sus supuestos. Un desacuerdo con la decisión no es, por sí solo, una causa de nulidad.",
    ], 'Solicitas una licencia y guardas el recibo de registro. Falta un documento y recibes requerimiento para subsanar. Después se incorporan informes, puedes alegar en los trámites correspondientes y el órgano competente resuelve. La notificación explica la decisión y cómo recurrir. Si no llega a tiempo, compruebas el plazo y el sentido del silencio previsto para esa licencia; no das por concedida cualquier autorización automáticamente.', '39 = expediente y garantías. LPAC y Ley 39/2015 son la misma norma. Localiza arts. 21-25, 30, 40-48 y 112-126.', boe('es/l/2015/10/01/39')),
    law('lrjsp', 'Ley 40/2015, de Régimen Jurídico del Sector Público', 'LRJSP · Ley 40/2015', '1 de octubre de 2015', 'Cómo se organiza y actúa el sector público y cómo se relacionan sus entidades.', [
      "Para qué sirve: distribuye funciones y ordena cómo actúa el sector público. La LPAC explica el recorrido del expediente; esta ley ayuda a saber quién decide y qué principios debe respetar.",
      "Competencia: cada órgano tiene tareas atribuidas por norma. Una unidad que prepara documentos no puede resolver por su cuenta si no tiene competencia. Esta es irrenunciable, aunque su ejercicio pueda delegarse en los términos legales.",
      "Delegación y avocación: delegar permite a otro ejercer una competencia manteniendo la titularidad. Avocar permite asumir motivadamente determinados asuntos en los supuestos legales. Por ejemplo, no es igual atribuir la gestión ordinaria a otro órgano que recuperar un expediente concreto.",
      "Encomienda, firma y suplencia: encomendar gestión encarga tareas materiales o técnicas, no la decisión jurídica. Delegar firma permite que otro firme; suplencia sustituye temporalmente al titular. Un trabajo técnico encargado a otra entidad no la autoriza a conceder una licencia.",
      "Abstención y recusación: protegen la imparcialidad. Si quien tramita un asunto tiene interés personal o una causa legal de parentesco debe apartarse; el interesado puede promover recusación. No basta afirmar que el empleado cree que puede ser objetivo.",
      "Principios sancionadores: no hay sanción sin cobertura normativa, tipificación y responsabilidad acreditada. Deben respetarse proporcionalidad y presunción de inocencia. No se inventa una multa porque una conducta parezca molesta.",
      "Responsabilidad patrimonial: un daño debe ser efectivo, evaluable, individualizado, antijurídico y causalmente conectado al servicio. Una caída en una calle no basta por sí sola: hay que analizar desperfecto, lesión, prueba y conducta de la víctima.",
      "Convenios y cooperación: Administraciones pueden colaborar con compromisos definidos. Un convenio no es una forma de eludir un contrato cuando su objeto es una prestación contractual; compartir un programa público no es lo mismo que comprar un servicio.",
    ], 'En un expediente sancionador compruebas qué órgano puede resolver y si existe delegación. Si una persona que interviene tiene una causa legal de conflicto, se plantea abstención. La sanción debe respetar legalidad y proporcionalidad. Para tramitar prueba, audiencia y notificación combinas estos principios con la Ley 39/2015.', '40 = organización y principios. Arts. 8-13: competencia; 23-24: imparcialidad; 25-31: sanciones; 32-37: responsabilidad.', boe('es/l/2015/10/01/40')),
    law('lrbrl', 'Ley 7/1985, Reguladora de las Bases del Régimen Local', 'LRBRL · LBRL · Ley de Bases del Régimen Local', '2 de abril de 1985', 'El marco básico de municipios, provincias y demás entidades locales.', [
      "Qué organiza: el municipio tiene territorio, población y organización; la provincia coordina y asiste en su ámbito. La autonomía local permite gestionar intereses propios dentro de la ley, sin convertir al Ayuntamiento en un Estado independiente.",
      "Población y padrón: el padrón registra residencia habitual y domicilio; inscribirse determina la condición de vecino. Vivir en Burgos y tener una vivienda de vacaciones en otra localidad no exige estar empadronado en ambas.",
      "Órganos: el Pleno tiene funciones normativas y de control; el alcalde dirige y representa; la Junta de Gobierno ejerce competencias ejecutivas según el régimen aplicable. No todos los acuerdos municipales los adopta el Pleno.",
      "Competencias y servicios: una competencia indica en qué materia puede intervenir; un servicio mínimo indica qué debe garantizar. La recogida de residuos es un ejemplo, pero las obligaciones aumentan según población y normativa.",
      "Ordenanzas: son normas municipales subordinadas a leyes. El procedimiento general incluye aprobación inicial, participación pública mínima de 30 días, resolución de reclamaciones, aprobación definitiva y publicación con requisitos de vigencia. La sola votación inicial no permite exigirla.",
      "Bienes y personal: establece bases de protección patrimonial y del empleo local. Una plaza destinada al uso público no se vende como un inmueble patrimonial; para personal se combina con TREBEP y normativa específica.",
      "Burgos y gran población: el Título X introduce especialidades en Pleno, alcalde, Junta y órganos de gestión. En un test sobre Burgos hay que comprobar este régimen antes de trasladar una regla del municipio ordinario.",
    ], 'Burgos quiere regular la utilización de un espacio municipal. Primero identifica competencia y órgano. Si aprueba una ordenanza, interviene el Pleno y se tramita participación y publicación. La gestión cotidiana y determinados acuerdos ejecutivos pueden corresponder a otros órganos según la ley: aprobar la norma y aplicarla son tareas diferentes.', 'LRBRL = Ayuntamiento. Arts. 25-26: competencias y servicios; 49: ordenanzas; 79-83: bienes; 121 y siguientes: gran población.', boe('es/l/1985/04/02/7')),
    law('ljca', 'Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa', 'LJCA', '13 de julio de 1998', 'Cómo se controla judicialmente la actuación administrativa.', [
      "Quién controla: juzgados y tribunales independientes revisan legalidad administrativa. No son superiores jerárquicos del alcalde; ejercen función judicial. El órgano competente depende del acto y de las reglas de esta ley.",
      "Qué puede impugnarse: actos recurribles, disposiciones inferiores a ley y determinados supuestos de inactividad o vía de hecho. Vía de hecho es una actuación material sin la cobertura jurídica exigible, no cualquier error del expediente.",
      "Acceso al proceso: debe existir legitimación y cumplirse requisitos, incluida la finalización de la vía administrativa cuando sea necesaria. Contra un acto expreso, el plazo ordinario es de dos meses, sin perjuicio de procedimientos especiales.",
      "Medidas cautelares: pedir al juez que suspenda una actuación busca evitar que la sentencia llegue demasiado tarde. No se conceden automáticamente por presentar demanda; se valoran circunstancias y los intereses en juego.",
      "Sentencia y ejecución: el juez puede anular, reconocer un derecho o imponer una actuación dentro de sus facultades. Si anula una sanción, la Administración debe cumplir el fallo; tampoco puede ignorarlo alegando que sigue pensando igual.",
    ], 'Después de agotar la vía administrativa cuando sea necesario, pides al juez que anule una sanción.', 'Un recurso administrativo lo resuelve la Administración; el contencioso, un órgano judicial.', boe('es/l/1998/07/13/29')),
    law('lcsp', 'Ley 9/2017, de Contratos del Sector Público', 'LCSP', '8 de noviembre de 2017', 'Cómo contrata el sector público obras, bienes y servicios.', [
      "Necesidad pública: antes de contratar se justifica para qué se necesita la prestación. Comprar equipos para una oficina debe responder a una necesidad definida; el expediente no empieza simplemente eligiendo la empresa preferida.",
      "Tipos: obra construye o reforma, suministro adquiere bienes y servicio contrata una actividad. Una concesión implica asumir riesgo operacional. Gestionar una instalación no es necesariamente concesión si ese riesgo no se transfiere.",
      "Capacidad y solvencia: el empresario debe poder contratar, no estar prohibido y acreditar medios económicos y técnicos cuando se exijan. Presentar la oferta más barata no corrige carecer de requisitos obligatorios.",
      "Pliegos: describen condiciones jurídicas y técnicas, obligaciones y criterios de valoración. Si la limpieza exige determinados horarios, medios y controles, las empresas deben ofertar conociéndolos y el adjudicatario cumplirlos.",
      "Importes: presupuesto base es límite de gasto de licitación, con IVA como regla; valor estimado, sin IVA, incorpora prórrogas y otras opciones previstas. Sirve para determinar reglas aplicables, por lo que no basta mirar una mensualidad aislada.",
      "Procedimientos: abierto permite ofertar a cualquier interesado que cumpla requisitos; restringido selecciona previamente candidatos; negociado solo cabe con habilitación. Publicidad y criterios objetivos evitan elegir arbitrariamente.",
      "Contrato menor: para obras inferiores a 40.000 euros y servicios o suministros inferiores a 15.000, sin IVA, en el régimen general. No permite dividir una necesidad para eludir controles y no puede durar más de un año ni prorrogarse.",
      "Adjudicación y ejecución: se selecciona la oferta conforme a criterios y después se formaliza cuando corresponde. Durante la ejecución se comprueba cumplimiento; una factura no acredita automáticamente que la prestación sea correcta.",
      "Cambios y extinción: modificar requiere causas y límites legales; no permite añadir cualquier prestación nueva. El contrato termina por cumplimiento o resolución en causas previstas; determinados actos admiten recurso especial.",
    ], 'El Ayuntamiento necesita limpiar un edificio. Justifica la necesidad, fija condiciones y presupuesto y tramita la licitación adecuada. Las empresas presentan ofertas que se comparan mediante los criterios publicados. Tras adjudicar y formalizar cuando corresponde, se comprueba que se limpia como se pactó; que la empresa envíe factura no evita el control del servicio.', 'LCSP = contratar. No confundas presupuesto base —con IVA, como regla— y valor estimado —sin IVA—.', boe('es/l/2017/11/08/9')),
    law('lgs', 'Ley 38/2003, General de Subvenciones', 'LGS', '17 de noviembre de 2003', 'Cómo se conceden, justifican y controlan ayudas públicas.', [
      "Qué es una subvención: entrega dineraria sujeta a una finalidad pública y condiciones, sin ser el precio de una prestación comprada. Ayudar a una asociación a organizar actividades no equivale a contratarle un servicio municipal.",
      "Bases y convocatoria: establecen quién puede participar, qué se financia, criterios, cuantías y plazos. Las bases son las reglas; la convocatoria abre el procedimiento concreto para solicitar la ayuda.",
      "Concesión: normalmente hay concurrencia competitiva y se comparan solicitudes; la concesión directa necesita supuesto legal. Un proyecto útil no basta para conceder dinero sin comprobar los requisitos.",
      "Obligaciones: el beneficiario realiza la actividad, acredita el destino del dinero y se somete a controles. Guardar facturas y demostrar resultados permite verificar que la ayuda cumplió su finalidad.",
      "Reintegro y sanción: incumplir puede obligar a devolver dinero y, si existe infracción, dar lugar a sanción. Devolver y sancionar son decisiones distintas; no todo reintegro supone automáticamente una multa.",
    ], 'Una asociación recibe ayuda para una actividad cultural y debe justificar el gasto subvencionado.', 'Subvención = fomentar una actividad; contrato = adquirir una prestación.', boe('es/l/2003/11/17/38')),
    law('lpap', 'Ley 33/2003, del Patrimonio de las Administraciones Públicas', 'LPAP', '3 de noviembre de 2003', 'El marco patrimonial público, con alcance distinto según cada Administración.', [
      "Clases de bienes: dominio público significa afectación a uso general o servicio público; patrimonial significa ausencia de ese destino en los términos legales. Una biblioteca y un local municipal disponible para alquiler no tienen el mismo régimen.",
      "Afectación: asignar el destino público cambia las reglas del bien. Desafectar requiere el procedimiento aplicable y puede permitir pasar al régimen patrimonial; dejar de usar físicamente un edificio no siempre produce automáticamente ese cambio.",
      "Protección: inventario y Registro ayudan a identificar bienes y acreditar derechos; investigación, deslinde y recuperación protegen el patrimonio. Hacer una lista de inmuebles no sustituye todos los títulos ni trámites.",
      "Uso y disposición: una ocupación privada del dominio público requiere título según su régimen; vender un patrimonial exige competencia y procedimiento. Tener la propiedad no autoriza al Ayuntamiento a actuar como un particular sin controles.",
      "Aplicación local: esta ley tiene disposiciones básicas y otras con alcance distinto. En Burgos se combina con LRBRL, TRRL y RBEL; no se traslada íntegramente el régimen patrimonial estatal a una entidad local.",
    ], 'Antes de vender un inmueble municipal debes determinar si es patrimonial o está afectado a un servicio público.', 'Titularidad pública no significa que todos los bienes tengan el mismo régimen.', boe('es/l/2003/11/03/33')),
  ] },
  { id: 'instituciones', title: 'Constitución e instituciones', groups: 'Grupo I y fuentes del Grupo II', laws: [
    law('ce', 'Constitución Española', 'CE', '27 de diciembre de 1978', 'La norma suprema que reconoce derechos y organiza los poderes públicos.', [
      "Estado y valores: España es un Estado social y democrático de Derecho; libertad, justicia, igualdad y pluralismo político son valores superiores. Social implica atención a necesidades; democrático, legitimidad popular; de Derecho, sometimiento a normas y controles.",
      "Soberanía y forma política: la soberanía reside en el pueblo español y la forma es monarquía parlamentaria. El Rey es jefe del Estado, pero no dirige libremente la política del Gobierno.",
      "Derechos: el Título I reconoce derechos y deberes con distinta protección. Igualdad y derechos de los arts. 14 a 29 tienen tutela reforzada; los principios rectores guían políticas y se alegan conforme a sus leyes de desarrollo.",
      "Poderes: Cortes legislan y controlan; Gobierno dirige y ejecuta; jueces juzgan y hacen ejecutar lo juzgado. El Tribunal Constitucional controla constitucionalidad y no es un tribunal ordinario del Poder Judicial.",
      "Territorio: municipios, provincias y comunidades autónomas tienen autonomía para gestionar intereses. El reparto de competencias impide que cualquier nivel regule cualquier materia por el solo hecho de considerarla importante.",
      "Administración: el art. 103 exige objetividad y sometimiento pleno a la ley y al Derecho. El art. 106 prevé control judicial y responsabilidad por daños en los términos legales: los poderes administrativos llevan garantías.",
      "Reforma: hay procedimiento ordinario y agravado según la materia afectada. Una ley ordinaria no puede modificar un precepto constitucional ni desplazar su protección.",
    ], 'Una ordenanza debe respetar la igualdad y los derechos constitucionales.', 'Referéndum: 6 de diciembre; sanción: 27; publicación y entrada en vigor: 29 de diciembre de 1978.', 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'),
    law('cc', 'Código Civil: título preliminar', 'CC', 'Real Decreto de 24 de julio de 1889', 'Las reglas generales para entender las fuentes y la aplicación del Derecho.', [
      "Fuentes: ley, costumbre y principios generales. La costumbre actúa en defecto de ley aplicable y con requisitos; los principios generales actúan en defecto de ambas y también informan el ordenamiento. No se salta una ley alegando una práctica habitual.",
      "Jurisprudencia: la doctrina reiterada del Tribunal Supremo complementa el ordenamiento al interpretar fuentes. Una sentencia aislada no equivale por sí sola a crear una ley nueva.",
      "Vigencia y derogación: si la ley no fija otra fecha, entra en vigor 20 días después de publicarse completamente en el BOE. Derogar elimina vigencia en su alcance; una norma posterior no borra necesariamente todo el texto anterior.",
      "Interpretación: se considera literalidad, contexto, antecedentes, realidad social y finalidad. Leer solo una palabra sin el resto del artículo puede llevar a una conclusión errónea.",
      "Analogía y límites: aplicar a un caso una norma de otro semejante exige identidad de razón y que no esté prohibido. No sirve para inventar infracciones o extender normas penales, excepcionales o temporales más allá de sus límites.",
    ], 'Si una ley no fija su entrada en vigor, la regla general es 20 días desde su publicación completa.', 'Aquí estudias principalmente cómo funcionan las normas, no todo el Derecho civil.', 'https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763'),
    law('gobierno', 'Ley 50/1997, del Gobierno', 'Ley del Gobierno', '27 de noviembre de 1997', 'La organización y el funcionamiento del Gobierno de España.', [
      "Composición y dirección: presidente coordina y dirige; vicepresidentes, si existen, y ministros desempeñan sus funciones. Consejo de Ministros adopta decisiones colegiadas; no es lo mismo que una decisión individual de un ministro.",
      "Funciones: la dirección política se acompaña de ejecución y potestad reglamentaria. El Gobierno presenta proyectos de ley, pero la aprobación parlamentaria de leyes corresponde a las Cortes.",
      "Funcionamiento: regula reuniones, órganos de apoyo y delegaciones en los términos permitidos. Delegar no permite trasladar cualquier facultad sin comprobar su régimen.",
      "Gobierno en funciones: mantiene continuidad con límites y se centra en despacho ordinario, salvo los supuestos admitidos. No tiene la misma libertad de impulso político que un Gobierno con plenas funciones.",
      "Elaboración normativa: proyectos y reglamentos requieren preparación, informes y participación según su procedimiento. Un reglamento gubernamental debe respetar Constitución, ley y competencias.",
    ], 'Para estudiar qué puede hacer un Gobierno en funciones combinas Constitución y esta ley.', 'Gobierno dirige la política; Administración sirve objetivamente al interés general.', boe('es/l/1997/11/27/50')),
    law('estatuto', 'Estatuto de Autonomía de Castilla y León', 'EACyL · LO 4/1983, reformada por LO 14/2007', '25 de febrero de 1983; reforma de 30 de noviembre de 2007', 'La norma institucional básica de Castilla y León.', [
      "Norma institucional básica: define Castilla y León dentro de España y de la Constitución. No es una constitución estatal independiente ni puede ampliar competencias al margen del marco constitucional.",
      "Derechos y principios: reconoce garantías y objetivos que guían la actuación autonómica. Su efectividad se analiza con la Constitución y las leyes de desarrollo; no todos generan una prestación concreta inmediata.",
      "Instituciones: Cortes legislan y controlan; presidente representa a la Comunidad y dirige la Junta; Junta es gobierno colegiado. Cortes autonómicas no son Cortes Generales.",
      "Competencias: determina materias y alcance de intervención autonómica. En unas hay legislación propia; en otras se desarrollan bases estatales o se ejecutan normas ajenas.",
      "Reforma: sigue iniciativa, mayorías y trámites estatutarios y requiere ley orgánica estatal. Una decisión de la Junta no basta para cambiar el Estatuto.",
      "Aplicación a Burgos: una materia municipal puede tener marco estatal y autonómico, pero Ayuntamiento y Junta son Administraciones distintas. La pertenencia territorial no convierte al alcalde en un órgano autonómico.",
    ], 'Para saber el papel de las Cortes autonómicas y de la Junta consultas el Estatuto.', 'Estatuto = organización de la Comunidad; LRBRL = bases de las entidades locales.', 'https://www.boe.es/buscar/act.php?id=BOE-A-1983-7474'),
    law('tue', 'Tratado de la Unión Europea', 'TUE', '7 de febrero de 1992; reformado, entre otros, por Lisboa (2007)', 'Los valores, objetivos y grandes reglas institucionales de la Unión.', [
      "Valores y objetivos: organiza una unión basada en democracia, derechos y Estado de Derecho, con objetivos comunes. Pertenecer a ella crea compromisos institucionales y jurídicos para los Estados.",
      "Atribución: la UE solo tiene las competencias cedidas por los tratados; las restantes corresponden a los Estados. Que un problema afecte a Europa no otorga por sí solo competencia ilimitada a la Unión.",
      "Subsidiariedad: en competencias no exclusivas se valora si actuar a escala europea consigue mejor el objetivo que actuar solo a escala estatal. No significa que cualquier municipio pueda vetar una norma europea.",
      "Proporcionalidad: la actuación no debe exceder lo necesario para los fines de los tratados. Competencia y proporción son comprobaciones diferentes.",
      "Instituciones: el Consejo Europeo fija orientación; Comisión propone y vela por cumplimiento; Parlamento y Consejo de la UE comparten normalmente legislación. Confundir ambos Consejos altera quién hace qué.",
      "Relación con TFUE: este tratado da marco de principios e instituciones; TFUE desarrolla competencias y funcionamiento. Se leen juntos, no como textos independientes sin conexión.",
    ], 'La UE solo actúa en competencias que los Estados le atribuyen mediante los tratados.', 'Consejo Europeo y Consejo de la UE son instituciones distintas.', 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12012M/TXT'),
    law('tfue', 'Tratado de Funcionamiento de la Unión Europea', 'TFUE', 'Denominación actual desde Lisboa, en vigor el 1 de diciembre de 2009', 'Desarrolla competencias, políticas y mecanismos de funcionamiento de la Unión.', [
      "Competencias y políticas: desarrolla mercado interior, competencia, transporte y otras materias. Para saber si la Unión puede legislar se comprueba ámbito y tipo de competencia.",
      "Mercado interior: facilita circulación dentro de la Unión bajo reglas comunes. No significa ausencia total de controles o de condiciones administrativas legítimas.",
      "Reglamento: obligatorio en todos sus elementos y directamente aplicable. El RGPD es un ejemplo; no necesita convertirse primero en una ley española para ser aplicable.",
      "Directiva: obliga al Estado destinatario a alcanzar un resultado dejando forma y medios en su marco. Las directivas de contratación se incorporaron mediante legislación nacional como la LCSP.",
      "Otros actos: decisión es obligatoria en sus términos; si designa destinatarios, para ellos. Recomendaciones y dictámenes no son vinculantes, aunque puedan orientar.",
      "Procedimientos y finanzas: regula mecanismos legislativos, presupuesto y controles. Una propuesta de Comisión todavía no equivale a una norma aprobada por quienes tienen competencia.",
    ], 'Un reglamento europeo es directamente aplicable; una directiva obliga al resultado y normalmente exige transposición.', 'TUE da el marco; TFUE desarrolla cómo funciona y qué hace la Unión.', 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12012E/TXT'),
  ] },
  { id: 'personal', title: 'Empleados públicos y protección social', groups: 'Grupo III', laws: [
    law('trebep', 'Texto refundido de la Ley del Estatuto Básico del Empleado Público', 'TREBEP · EBEP · RDL 5/2015', '30 de octubre de 2015', 'Las bases del empleo público, con preceptos aplicables según el tipo de personal.', [
      "Clases de personal: carrera tiene vínculo estatutario permanente; interino cubre necesidades temporales legalmente previstas; laboral tiene contrato; eventual realiza confianza o asesoramiento especial. No basta saber que todos cobran del Ayuntamiento para aplicarles idénticas reglas.",
      "Acceso: selección basada en igualdad, mérito, capacidad y publicidad. La convocatoria fija requisitos y pruebas. Una oposición comprueba conocimientos o aptitudes; un concurso valora méritos en los supuestos admitidos.",
      "Adquisición: superar el proceso no completa por sí solo la condición de carrera. Faltan nombramiento publicado, acatamiento y toma de posesión; aprobar y adquirir la condición son momentos distintos.",
      "Provisión: asigna un puesto a quien reúne los requisitos. El concurso de provisión no es necesariamente un concurso de ingreso; libre designación requiere convocatoria y se reserva a los puestos previstos.",
      "Carrera y promoción: progresar en la trayectoria profesional no siempre exige cambiar de puesto. Promoción interna permite acceder a otros cuerpos o escalas cumpliendo requisitos y proceso; antigüedad sola no lo concede automáticamente.",
      "Derechos y deberes: retribución, formación, conciliación y descanso conviven con imparcialidad, confidencialidad y diligencia. Saber un dato por el trabajo no autoriza a compartirlo con una amistad.",
      "Situaciones: activo, servicios especiales, servicio en otras Administraciones, excedencias y suspensión tienen efectos distintos. Hay que preguntar si se cobra, qué tiempo cuenta y si existe reserva o derecho de reingreso.",
      "Disciplina: incumplir deberes puede generar sanción con tipificación y garantías. La separación del servicio afecta a la condición; cambiar de puesto no equivale necesariamente a perderla.",
    ], 'Superas una oposición y completas nombramiento y toma de posesión. Ya como funcionario, puedes participar en procedimientos de provisión para cambiar de puesto o en promoción interna si reúnes requisitos. Si solicitas excedencia, debes identificar su modalidad para saber sus efectos. Cambiar de puesto, quedar en excedencia y perder la condición funcionarial son situaciones diferentes.', 'TREBEP = bases del empleado público. EBEP suele usarse como nombre corto; el texto refundido vigente se aprobó en 2015.', boe('es/rdlg/2015/10/30/5')),
    law('et', 'Texto refundido de la Ley del Estatuto de los Trabajadores', 'ET · RDL 2/2015', '23 de octubre de 2015', 'La norma básica de las relaciones laborales, también relevante para personal laboral público.', [
      "Ámbito: regula relaciones laborales por contrato. En personal laboral público se combina con convenio y preceptos aplicables del TREBEP; un funcionario de carrera no se vincula mediante el mismo contrato laboral.",
      "Contrato: determina vínculo y condiciones dentro de los límites legales. La temporalidad exige causa; que un empleador sea Administración no permite encadenar contratos sin respetar reglas.",
      "Jornada y salario: establece garantías sobre tiempo de trabajo, descanso y retribución. El convenio concreta condiciones válidas, pero no puede eliminar derechos obligatorios por acuerdo individual.",
      "Suspensión y extinción: suspender interrumpe temporalmente determinadas obligaciones manteniendo el vínculo; extinguir lo termina. Una baja o permiso no equivale a un despido.",
      "Representación y negociación: trabajadores tienen representantes y pueden negociar mediante instrumentos legales. En empleo público también operan límites presupuestarios y principios de acceso: el convenio no convierte automáticamente a temporal en fijo.",
      "Selección pública: el contrato no permite elegir personal como cualquier empresa privada. Igualdad, mérito, capacidad y publicidad siguen siendo esenciales para acceder al Ayuntamiento.",
    ], 'El personal laboral municipal se rige por normas laborales y también por las disposiciones públicas que le correspondan.', 'ET no sustituye al TREBEP para todo el empleo público.', boe('es/rdlg/2015/10/23/2')),
    law('incompatibilidades', 'Ley 53/1984, de incompatibilidades del personal al servicio de las Administraciones Públicas', 'Ley de incompatibilidades', '26 de diciembre de 1984', 'Proteger dedicación, independencia e imparcialidad ante otras actividades.', [
      "Finalidad: preservar dedicación al servicio e imparcialidad. Se aplica a personal público con independencia de que su vínculo sea funcionarial o laboral; trabajar por contrato no elimina el régimen.",
      "Segundo puesto público: la regla es incompatibilidad, con excepciones legalmente previstas y autorización. Tener horarios diferentes no basta para permitir dos empleos públicos.",
      "Actividad privada: se comprueban relación con las funciones, conflicto, horario y restricciones. Una gestoría que tramita asuntos sobre los que el empleado decide puede comprometer su imparcialidad aunque trabaje por la tarde.",
      "Autorización previa: cuando se exige, debe obtenerse antes de iniciar la actividad. No es un permiso automático por solicitarlo ni modifica la jornada del puesto público.",
      "Excepciones: la ley exceptúa determinadas actividades del régimen en sus condiciones, como ciertas colaboraciones ocasionales. Hay que comprobar el supuesto real, no dar por compatible cualquier actividad que parezca pequeña.",
      "Incumplimiento: puede generar responsabilidad disciplinaria y otras consecuencias. Ocultar la segunda actividad no evita el conflicto ni el deber de cumplir la ley.",
    ], 'Quien tramita asuntos de una empresa no puede asesorarla privadamente en condiciones incompatibles con su puesto.', 'Se aplica también a personal laboral público; no basta hacer la actividad fuera del horario.', boe('es/l/1984/12/26/53')),
    law('lols', 'Ley Orgánica 11/1985, de Libertad Sindical', 'LOLS', '2 de agosto de 1985', 'La libertad de crear sindicatos, afiliarse y desarrollar actividad sindical.', [
      "Libertad individual: incluye afiliarse, no afiliarse y participar en actividad sindical con las condiciones aplicables. La afiliación no debe convertirse en motivo de trato desfavorable.",
      "Libertad colectiva: sindicatos se organizan y actúan para defender intereses profesionales. Su papel no es resolver expedientes individuales ni asumir competencias de gobierno municipal.",
      "Acción en el centro: secciones y delegados sindicales actúan con las garantías previstas. La representación sindical y la representación unitaria del personal son figuras relacionadas, pero diferentes.",
      "Representatividad: ciertos derechos y facultades dependen de los criterios legales. La existencia de un sindicato no le concede automáticamente todas las facultades de uno más representativo.",
      "Tutela: las vulneraciones pueden impugnarse. La huelga se conecta con libertad sindical, pero se estudia también desde la Constitución y su normativa específica.",
    ], 'El empleado puede participar en actividad sindical bajo las garantías y condiciones aplicables.', 'Sindicación y huelga están relacionadas, pero la LOLS no contiene toda la regulación de la huelga.', boe('es/lo/1985/08/02/11')),
    law('lgss', 'Texto refundido de la Ley General de la Seguridad Social', 'TRLGSS · LGSS · RDL 8/2015', '30 de octubre de 2015', 'La estructura del sistema y su protección frente a situaciones de necesidad.', [
      "Sistema: protege frente a situaciones de necesidad mediante regímenes y prestaciones. Contributivo se vincula a cotizaciones; no contributivo exige sus propios requisitos de residencia, recursos u otros, no simplemente ausencia de empleo.",
      "Afiliación, alta y baja: afiliación identifica en el sistema; alta refleja actividad y baja su cese. Cambiar de empleo puede implicar nueva alta sin una nueva afiliación completamente distinta.",
      "Cotización: trabajador y empleador aportan según reglas aplicables. Base de cotización no equivale siempre al salario neto que se ingresa en el banco.",
      "Contingencias: enfermedad común y accidente no laboral son comunes; accidente de trabajo y enfermedad profesional son profesionales. Determinar la causa influye en requisitos, cuantía y gestión.",
      "Incapacidad: temporal supone impedimento transitorio para trabajar; permanente responde a reducciones funcionales en sus grados legales. Una baja prolongada no equivale automáticamente a incapacidad permanente.",
      "Prestaciones: jubilación, nacimiento y cuidado, desempleo y muerte y supervivencia responden a necesidades distintas. Estar afiliado no basta siempre: se comprueban requisitos de cada prestación.",
      "Entidades: INSS gestiona y reconoce muchas prestaciones; TGSS se ocupa de afiliación y recaudación; SEPE y otras entidades intervienen en sus ámbitos. No se solicita todo al mismo organismo.",
    ], 'Una baja por accidente de trabajo y otra por enfermedad común pueden tener reglas distintas.', 'Contingencia = causa protegida; prestación = respuesta del sistema, con sus requisitos.', boe('es/rdlg/2015/10/30/8')),
  ] },
  { id: 'economia', title: 'Hacienda local, presupuesto y urbanismo', groups: 'Grupo IV', laws: [
    law('trlrhl', 'Texto refundido de la Ley Reguladora de las Haciendas Locales', 'TRLRHL · TRLHL · RDL 2/2004', '5 de marzo de 2004', 'De dónde obtiene recursos el Ayuntamiento y cómo organiza su presupuesto y gasto.', [
      "Recursos locales: el Ayuntamiento obtiene ingresos por tributos, participación en recursos de otras Administraciones, subvenciones y otros medios legales. Ingreso previsto no significa dinero ya disponible para cualquier gasto.",
      "Impuestos: IBI grava inmuebles; IAE, actividades económicas; IVTM, vehículos, con sus requisitos y exenciones. ICIO e IIVTNU son potestativos; no basta llamar a un cobro impuesto para poder crearlo.",
      "Tasas y precios públicos: tasa puede vincularse a aprovechamiento especial del dominio público o a servicios en condiciones legales. Precio público responde a servicios voluntarios y también prestados por el sector privado; no son categorías intercambiables.",
      "Ordenanza fiscal: concreta elementos permitidos por la ley y se aprueba y publica mediante procedimiento específico. El Ayuntamiento no puede inventar un tributo solo porque necesite financiarse.",
      "Presupuesto: prevé ingresos y autoriza gastos limitados por finalidad, cuantía y ejercicio. Tener dinero en Tesorería no sustituye un crédito adecuado para el gasto.",
      "Modificaciones: crédito extraordinario crea uno inexistente; suplemento aumenta uno insuficiente y no ampliable. Transferencia mueve crédito entre aplicaciones; cada modificación necesita financiación, competencia y expediente.",
      "Ejecución: autorizar decide el gasto; disponer compromete con tercero; reconocer obligación acredita deuda exigible; ordenar pago antecede al pago material. Contratar y pagar no son el mismo paso.",
      "Liquidación y cuentas: al terminar el ejercicio se determina qué se ejecutó y se rinden cuentas. El presupuesto aprobado es una previsión autorizada; la liquidación muestra su resultado.",
    ], 'Se prevé comprar un vehículo municipal. Si no existe crédito adecuado, antes de contratar debe tramitarse la modificación que corresponda. Después se autoriza el gasto, se compromete con la adjudicación, se reconoce la obligación al recibir y comprobar el vehículo y se ordena pagar. La transferencia final es el pago material: llega después de las decisiones y controles previos.', 'LRBRL = organización local; TRLRHL = dinero local. Arts. 15-19: ordenanzas fiscales; 162 y siguientes: presupuesto.', boe('es/rdlg/2004/03/05/2')),
    law('lgt', 'Ley 58/2003, General Tributaria', 'LGT', '17 de diciembre de 2003', 'Las reglas generales de los tributos y de su aplicación.', [
      "Tributo: prestación exigida conforme a la ley. Hecho imponible es el supuesto que origina la obligación; sujeto obligado es quien debe cumplirla. Ser propietario puede ser relevante para un impuesto, pero hay que leer su regulación concreta.",
      "Cálculo: base y tipo sirven para determinar cuota bajo las reglas del tributo. Deuda tributaria puede incluir conceptos adicionales previstos, por lo que no siempre coincide con la cuota inicialmente calculada.",
      "Gestión e inspección: gestión tramita y comprueba en su ámbito; inspección investiga y regulariza con sus potestades y garantías. Una solicitud de información no equivale automáticamente a una sanción.",
      "Recaudación: primero existe periodo voluntario; el impago puede llevar a periodo ejecutivo, recargos y apremio. El cobro forzoso requiere título y procedimiento, no una decisión informal.",
      "Infracciones: deben probarse y sancionarse con reglas propias. Una liquidación adicional y una sanción son decisiones distintas; no todo error genera culpabilidad sancionable.",
      "Revisión: recursos y reclamaciones tributarias tienen especialidades. En Burgos se comprueba el régimen de gran población y el órgano económico-administrativo; no se aplica sin más la reposición ordinaria de LPAC.",
    ], 'La normativa del IBI define ese impuesto; la LGT aporta reglas generales para gestionarlo y recaudarlo.', 'Procedimiento tributario tiene especialidades: no traslades automáticamente todos los recursos de la LPAC.', boe('es/l/2003/12/17/58')),
    law('loepsf', 'Ley Orgánica 2/2012, de Estabilidad Presupuestaria y Sostenibilidad Financiera', 'LOEPSF', '27 de abril de 2012', 'La disciplina financiera del conjunto de Administraciones.', [
      "Estabilidad: disciplina sobre el equilibrio de las cuentas públicas conforme a las reglas aplicables. Aprobar un presupuesto formalmente no demuestra por sí solo que cumple todas las exigencias financieras.",
      "Sostenibilidad: capacidad para financiar compromisos presentes y futuros. Un servicio con coste inicial pequeño puede generar cargas de mantenimiento que deben analizarse.",
      "Gasto y deuda: existen reglas y límites en su marco de aplicación. No se deben memorizar objetivos anuales como si fueran cifras permanentes escritas para siempre en la ley.",
      "Información: transparencia y seguimiento permiten detectar riesgos e incumplimientos. La decisión económica necesita datos fiables, no solo una previsión optimista.",
      "Medidas correctivas: incumplir puede exigir planes y ajustes. Su finalidad es recuperar cumplimiento; no equivale a prohibir automáticamente toda actividad municipal.",
    ], 'Una iniciativa económica municipal debe valorar si compromete la sostenibilidad de la Hacienda local.', 'Tener crédito es necesario, pero no elimina las demás condiciones de disciplina financiera.', boe('es/lo/2012/04/27/2')),
    law('suelo', 'Texto refundido de la Ley de Suelo y Rehabilitación Urbana', 'TRLSRU · RDL 7/2015', '30 de octubre de 2015', 'Las bases estatales del régimen del suelo y la rehabilitación.', [
      "Marco estatal: establece bases de derechos y deberes del ciudadano y de la propiedad vinculados al suelo. La clasificación y el planeamiento concretos se completan en la normativa autonómica y municipal.",
      "Propiedad: ser dueño no concede libertad ilimitada para urbanizar o edificar. Hay deberes y condiciones que dependen del régimen de la actuación y del terreno.",
      "Situaciones básicas: distingue rural y urbanizado en su marco. No son la misma clasificación que urbano, urbanizable y rústico utilizada por legislación urbanística autonómica.",
      "Valoración: fija criterios para determinados supuestos, como expropiación. Una expectativa de poder construir en el futuro no se trata necesariamente como una edificación ya realizada.",
      "Rehabilitación: conecta actuaciones sobre ciudad y edificios existentes con derechos y obligaciones. Recuperar un inmueble también requiere cumplir normativa y títulos aplicables.",
    ], 'Valorar un terreno exige atender a las reglas estatales, además de su ordenación urbanística.', 'Situación básica estatal y clasificación urbanística autonómica no son expresiones intercambiables.', boe('es/rdlg/2015/10/30/7')),
    law('lucyl', 'Ley 5/1999, de Urbanismo de Castilla y León', 'LUCyL', '8 de abril de 1999', 'Las reglas urbanísticas autonómicas que aplica el Ayuntamiento de Burgos.', [
      "Clasificación del suelo: determina categorías y régimen en Castilla y León. Un suelo rústico no permite los mismos usos que un solar urbano; el destino depende de reglas y protección aplicables.",
      "Planeamiento: organiza usos, intensidades, dotaciones y condiciones. La calificación concreta qué puede hacerse; una clasificación por sí sola no detalla todos los parámetros de una parcela.",
      "Gestión: permite ejecutar el planeamiento y distribuir beneficios y cargas en sus términos. Diseñar una nueva zona y materializar calles y servicios son operaciones distintas.",
      "Licencias y declaraciones: controlan actuaciones según el título legalmente exigido. Presentar declaración responsable no permite una obra prohibida por el plan.",
      "Restauración: puede paralizar, exigir legalización si es posible o reponer la realidad alterada. Haber pagado una multa no legaliza una construcción.",
      "Sanción: castiga infracciones mediante procedimiento y garantías. La restauración protege el orden urbanístico y la sanción responde al incumplimiento; sus plazos y efectos deben estudiarse separadamente.",
    ], 'Una obra sin título habilitante puede exigir paralización y restauración, y además generar sanción.', 'Restaurar corrige la situación ilegal; sancionar castiga la infracción.', boe('es-cl/l/1999/04/08/5')),
  ] },
  { id: 'derechos', title: 'Igualdad, ciudadanía, datos y prevención', groups: 'Grupo V', laws: [
    law('igualdad', 'Ley Orgánica 3/2007, para la igualdad efectiva de mujeres y hombres', 'Ley de igualdad', '22 de marzo de 2007', 'Prevenir discriminación y hacer efectiva la igualdad entre mujeres y hombres.', [
      "Igualdad efectiva: no basta tratar formalmente igual si persisten obstáculos. La actuación pública debe prevenir desigualdades y revisar sus efectos sobre mujeres y hombres.",
      "Discriminación directa: trato menos favorable por sexo. Indirecta: criterio aparentemente neutro que produce desventaja particular sin justificación legítima y proporcionada; puede aparecer en reglas de acceso o condiciones de trabajo.",
      "Acoso: sexual y por razón de sexo tienen definiciones distintas y ambos lesionan igualdad y dignidad. La atención no debe minimizar una denuncia por considerarla una simple broma.",
      "Transversalidad: igualdad se integra en educación, empleo, contratación y políticas públicas. No es competencia exclusiva de un departamento que libera de responsabilidad a todos los demás.",
      "Empleo público: selección y condiciones deben respetar igualdad y medidas aplicables de conciliación y prevención. Conciliar no supone automáticamente renunciar a carrera o recibir peor trato.",
      "Acción positiva: medidas específicas pueden corregir desigualdades de hecho bajo condiciones legales. Igualdad no significa que toda medida diferenciada sea automáticamente discriminatoria.",
    ], 'Una regla aparentemente neutra puede ser discriminatoria si genera desventaja injustificada por sexo.', 'Igualdad formal prohíbe discriminar; igualdad efectiva exige actuar sobre obstáculos.', boe('es/lo/2007/03/22/3')),
    law('violencia', 'Ley Orgánica 1/2004, de Medidas de Protección Integral contra la Violencia de Género', 'Ley de protección integral', '28 de diciembre de 2004', 'Prevenir y atender la violencia de género definida en su ámbito legal.', [
      "Ámbito: la ley define específicamente violencia de género sobre mujeres por parejas o exparejas varones, con previsiones relacionadas de protección. No toda violencia entre familiares se encuadra en ese concepto.",
      "Protección integral: combina prevención, sensibilización, asistencia social, respuesta institucional y medidas jurídicas. No se limita a castigar después de una agresión.",
      "Derechos: información, atención especializada y medidas laborales, sociales y económicas en los términos legales. La persona debe conocer a qué recursos puede acceder sin tener que descubrirlos sola.",
      "Actuación administrativa: se comprueba la acreditación exigida para cada derecho y se deriva a servicios competentes. No debe afirmarse que todos los apoyos requieren necesariamente una única forma de acreditación.",
      "Confidencialidad: manejar dirección, contactos y datos con prudencia protege a la víctima. Repetir innecesariamente el relato o revelar su ubicación puede agravar el daño.",
      "Coordinación: Ayuntamiento, servicios sociales y otros recursos actúan en sus competencias. Quien atiende orienta y deriva; no sustituye una valoración especializada ni exige detalles sin necesidad.",
    ], 'La oficina deriva a recursos especializados y protege la confidencialidad de una víctima.', 'No toda violencia familiar coincide con el concepto específico de esta ley.', boe('es/lo/2004/12/28/1')),
    law('lgtbi', 'Ley 4/2023, para la igualdad real y efectiva de las personas trans y para la garantía de los derechos de las personas LGTBI', 'Ley trans y LGTBI', '28 de febrero de 2023', 'Garantizar igualdad de trato y prevenir discriminación por las causas protegidas.', [
      "Objeto: igualdad real de personas trans y garantía de derechos LGTBI. Abarca discriminación y políticas públicas además de rectificación registral.",
      "Trato y respeto: identidad y orientación no deben originar obstáculos administrativos injustificados. Se comprueba la documentación que corresponda sin convertir el trámite en interrogatorio sobre la vida privada.",
      "Ámbitos: educación, salud, empleo y servicios públicos necesitan medidas de prevención y atención. Una regla de acceso a instalaciones también puede tener efectos discriminatorios.",
      "Rectificación registral: establece procedimientos y condiciones según supuestos, incluidas diferencias por edad. No es correcto describir todo el régimen como un trámite idéntico para cualquier persona.",
      "Obligaciones públicas: formación, atención y respuesta frente a discriminación en los términos legales. Debe distinguirse la explicación general del derecho del órgano que resuelve una actuación registral.",
      "Aplicación diaria: la oficina evita formularios y expresiones que excluyan innecesariamente, facilita el trámite y protege datos personales.",
    ], 'El personal municipal presta atención respetuosa y evita requisitos o trato discriminatorios.', 'Su alcance no se reduce al cambio registral: incluye políticas y garantías de igualdad.', boe('es/l/2023/02/28/4')),
    law('transparencia', 'Ley 19/2013, de transparencia, acceso a la información pública y buen gobierno', 'Ley de transparencia', '9 de diciembre de 2013', 'Abrir la información pública y exigir responsabilidad en el gobierno.', [
      "Información pública: contenidos y documentos en poder de sujetos obligados elaborados o adquiridos en ejercicio de sus funciones. Pedir un expediente existente es distinto de exigir que se redacte un estudio nuevo.",
      "Publicidad activa: publicar por iniciativa propia información institucional, jurídica y económica exigible. Presupuestos y contratación son ejemplos; publicar una noticia promocional no cumple por sí solo todas las obligaciones.",
      "Solicitud: identifica al solicitante y qué información pide; no exige justificar por qué la quiere. Si resulta imprecisa, se tramita su concreción en los términos legales.",
      "Límites: seguridad, intereses protegidos y datos personales se ponderan y motivan. No se deniega todo un documento cuando puede facilitarse una parte sin revelar información protegida.",
      "Inadmisión: opera por causas legales, como determinados supuestos de reelaboración; es distinta de aplicar un límite al contenido. No toda extracción informática sencilla equivale a reelaborar.",
      "Plazo y silencio: un mes desde recepción por el órgano competente, ampliable otro por volumen o complejidad con comunicación. El silencio es desestimatorio y admite las vías legales de reclamación o control.",
      "Buen gobierno: incluye deberes y responsabilidad para los sujetos a los que se aplica. Transparencia sobre una decisión y responsabilidad por adoptarla son planos relacionados, pero distintos.",
    ], 'Publicar el presupuesto es publicidad activa; responder a una solicitud de información es derecho de acceso.', 'Transparencia se combina con protección de datos: publicar no significa revelar todo.', boe('es/l/2013/12/09/19')),
    law('discapacidad', 'Texto refundido de la Ley General de derechos de las personas con discapacidad y de su inclusión social', 'RDL 1/2013', '29 de noviembre de 2013', 'Garantizar derechos, inclusión e igualdad de oportunidades.', [
      "Enfoque de derechos: la discapacidad se analiza también por las barreras que dificultan participación. Una persona puede realizar un trámite correctamente si el entorno y la comunicación resultan accesibles.",
      "Accesibilidad universal: diseña servicios utilizables desde el principio, tanto físicos como digitales. Entrada sin escalones y formulario comprensible son ejemplos diferentes de la misma finalidad.",
      "Ajustes razonables: adaptación necesaria para un caso concreto, con sus condiciones legales. Facilitar un canal o apoyo adecuado no es un favor personal del empleado.",
      "No discriminación: reglas aparentemente comunes pueden excluir injustificadamente. Debe valorarse la barrera real y el ajuste que permite ejercer el derecho.",
      "Atención: dirigirse a la persona, preguntar por el apoyo que necesita y explicar con claridad, evitando suponer incapacidad por apariencia o diagnóstico.",
    ], 'Se adapta la atención para que una persona pueda comprender y completar su trámite.', 'Accesibilidad no consiste solo en eliminar escalones: incluye información y comunicación.', boe('es/rdlg/2013/11/29/1')),
    law('prl', 'Ley 31/1995, de Prevención de Riesgos Laborales', 'LPRL', '8 de noviembre de 1995', 'Evitar daños del trabajo mediante una prevención organizada.', [
      "Prevención integrada: forma parte de la organización del trabajo, no solo de actuar tras un accidente. Una oficina tiene riesgos aunque no use maquinaria industrial.",
      "Evaluación: identifica peligros y estima sus riesgos. Planificación decide medidas, responsables y plazos; evaluar una mala postura sin corregirla no completa la prevención.",
      "Principios: evitar riesgos y combatirlos en origen, adaptar trabajo a persona y priorizar protección colectiva. Mejorar diseño de un puesto suele proteger más que confiar solo en que el empleado aguante molestias.",
      "Información y formación: explicar riesgos y enseñar actuación segura son obligaciones diferentes. Entregar un documento no acredita automáticamente que la formación sea suficiente.",
      "Salud y emergencias: vigilancia con confidencialidad y consentimiento como regla, salvo excepciones; medidas ante emergencia y riesgo grave e inminente. El superior no debe recibir indiscriminadamente diagnósticos médicos.",
      "Oficina: pantalla, iluminación, silla, movimientos repetitivos y carga mental requieren medidas concretas. Los riesgos psicosociales también forman parte de la prevención.",
      "Participación y deberes: trabajadores usan medios correctamente y comunican riesgos; delegados y órganos preventivos participan según la ley. La responsabilidad del empleador no desaparece porque el trabajador tenga obligaciones.",
    ], 'En una oficina se revisan postura, pantallas, iluminación y carga mental.', 'Prevenir = anticiparse. Art. 15: principios; 16: evaluación y planificación; 22: vigilancia de salud.', boe('es/l/1995/11/08/31')),
    law('rgpd', 'Reglamento (UE) 2016/679, General de Protección de Datos', 'RGPD', '27 de abril de 2016; aplicable desde el 25 de mayo de 2018', 'Las reglas europeas para tratar datos personales.', [
      "Qué protege: datos que identifican o permiten identificar personas, como nombre, DNI, dirección y combinaciones de información. Quitar el nombre no anonimiza si otros datos permiten reconocer a la persona.",
      "Base jurídica: cada tratamiento necesita habilitación. La Administración usa frecuentemente obligación legal o interés público; no debe pedir consentimiento como solución universal para trámites obligatorios.",
      "Finalidad y minimización: recoger datos para un objetivo concreto y solo los necesarios. Solicitar historial médico completo para un trámite que no lo requiere sería excesivo.",
      "Exactitud y conservación: corregir datos inexactos y conservar conforme a necesidad y obligaciones legales. Un expediente no se borra solo porque alguien pida supresión si existe deber de conservación.",
      "Roles: responsable decide fines y medios; encargado trabaja por su cuenta bajo condiciones; delegado asesora y supervisa. Una empresa que aloja datos municipales no decide libremente reutilizarlos.",
      "Derechos: acceso, rectificación, supresión, oposición, limitación y portabilidad en los supuestos legales. Saber qué datos se tratan y obtener copia no equivale a acceder sin límites a datos ajenos.",
      "Seguridad y brechas: proteger accesos y responder a incidentes. Enviar un listado a destinatario equivocado puede ser brecha; se evalúa el riesgo y se cumplen notificaciones cuando proceden.",
      "Responsabilidad proactiva: demostrar que se cumplen obligaciones mediante medidas y documentación. Tener una cláusula informativa no sustituye organizar permisos, conservación y seguridad.",
    ], 'Una ayuda se tramita con los datos necesarios y acceso limitado al personal autorizado.', 'RGPD es un reglamento europeo directamente aplicable, no una ley española.', 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:32016R0679'),
    law('lopdgdd', 'Ley Orgánica 3/2018, de Protección de Datos Personales y garantía de los derechos digitales', 'LOPDGDD', '5 de diciembre de 2018', 'Complementar el RGPD en España y reconocer derechos digitales.', [
      "Relación con RGPD: concreta aspectos nacionales permitidos por el reglamento. Se aplican conjuntamente; no se elige una u otra según resulte más cómoda.",
      "Garantías nacionales: precisa reglas para determinados tratamientos y ejercicio de derechos. Leer el reglamento europeo da el marco y la ley española aporta particularidades.",
      "Autoridades y control: regula aspectos del sistema español de supervisión y responsabilidades. El delegado interno no sustituye a la autoridad de protección de datos.",
      "Derechos digitales: incluye intimidad ante dispositivos, videovigilancia y geolocalización laborales y desconexión, según sus condiciones. Un equipo corporativo no elimina todos los derechos del empleado.",
      "Desconexión: protege descanso fuera del tiempo de trabajo en su régimen; deben existir políticas y reglas aplicables. Que el correo pueda recibirse a cualquier hora no obliga automáticamente a contestarlo.",
      "Trabajo municipal: revisar finalidad, información al ciudadano, permisos y canal de envío. Dar acceso completo a toda la plantilla no se justifica por el mero hecho de que todos sean empleados públicos.",
    ], 'El uso de dispositivos corporativos debe atender a reglas de protección de datos y garantías digitales.', 'RGPD y LOPDGDD se estudian juntos; la ley española no sustituye al reglamento europeo.', boe('es/lo/2018/12/05/3')),
  ] },
];

